function Progress({value,color}:{value:number;color?:string}){return <div className="progress"><span style={{width:Math.min(100,Math.max(0,value))+'%',background:color}}/></div>;}
function Empty({children,action}:{children:ReactNode;action?:ReactNode}){return <div className="empty"><Sun size={24}/><p>{children}</p>{action}</div>;}
function Head({title,subtitle,children,className=""}:{title:string;subtitle?:string;children?:ReactNode;className?:string}){return <header className={cn("page-head",className)}><div><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div><div className="head-controls">{children}</div></header>;}
function Dialog({title,children,onClose,wide=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean}){const error=useContext(ErrorContext);const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const el=ref.current;el?.showModal();return()=>el?.close();},[]);return <dialog ref={ref} className={cn('modal',wide&&'wide')} onCancel={e=>{e.preventDefault();onClose();}} aria-label={title}><header><h2>{title}</h2><button type="button" className="icon-btn" aria-label={ui("关闭")} onClick={onClose}><X/></button></header>{children}{error&&<p role="alert" className="inline-error">{ui(error)}</p>}</dialog>;}
function DateNav({date,setDate,today}:{date:string;setDate:(v:string)=>void;today:string}){return <div className="date-nav"><button aria-label={ui("前一天")} onClick={()=>setDate(offsetDate(date,-1))}><ChevronLeft/></button><input aria-label={ui("查看日期")} type="date" value={date} onInput={e=>e.currentTarget.value&&setDate(e.currentTarget.value)} onChange={e=>e.target.value&&setDate(e.target.value)}/><button onClick={()=>setDate(today)}>{ui("今天")}</button><button aria-label={ui("后一天")} onClick={()=>setDate(offsetDate(date,1))}><ChevronRight/></button></div>;}
export function TaskEditor({draft,state,busy,save,close,remove,template,guideHint,mutate}:{draft:TaskDraft;state:State;busy:boolean;mutate:(c:Command,message?:string)=>Promise<boolean>;save:(d:TaskDraft)=>Promise<void>;close:()=>void;remove:(scope:TaskDraft['scope'])=>void;template:(t:TaskInput,kind?:ResidentKind)=>void;guideHint?:string}){
 const [scheduleOpen,setScheduleOpen]=useState(false),[scheduleEditing,setScheduleEditing]=useState(false);
 const live=draft.existing?state.tasks.find(x=>x.id===draft.id):undefined;
 const [d,setD]=useState(draft),[dirty,setDirty]=useState(false),[entryKind,setEntryKind]=useState<'once'|ResidentKind>('once');const t=d.task;const set=(key:keyof TaskInput,value:unknown)=>{setDirty(true);setD(p=>({...p,task:{...p.task,[key]:value,...(key==='projectId'?{moduleId:''}:{})}}));};
 const backToTask=()=>{if(!busy&&(!scheduleEditing||confirm(ui('放弃尚未保存的时间安排？')))){setScheduleOpen(false);setScheduleEditing(false);}};
 const dismiss=()=>{if(busy)return;if(scheduleOpen){backToTask();return;}if(!dirty||confirm(ui("放弃尚未保存的修改？")))close();};const end=t.start&&t.minutes?clock(Math.min(1440,minuteOf(t.start)+t.minutes)):'';
 return <Dialog title={scheduleOpen?ui('调整时间安排'):d.existing?ui("编辑事项"):ui("新建事项")} onClose={dismiss} wide>{scheduleOpen&&live?<div className="task-editor-schedule-view"><button type="button" disabled={busy} onClick={backToTask}>← {ui('返回编辑事项')}</button><h3>{t.title}</h3><p className="hint">{ui('时间安排单独保存；返回后可继续编辑标题和备注。开始时间可以留空。')}</p><TaskPlanEditor task={live} state={state} busy={busy} mutate={mutate} initiallyEditing onEditingChange={setScheduleEditing}/></div>:<form onSubmit={e=>{e.preventDefault();if(entryKind!=='once')template(t,entryKind);else void save(live?{...d,existing:live,task:{...d.task,actual:live.actual,progress:live.progress,progressSource:live.progressSource,...(live.plans?{date:live.date,start:live.start,minutes:live.minutes}:{})}}:d);}}><fieldset disabled={busy}><p className="muted">{guideHint||ui("这里只修改计划。实际做了多久，可在任务旁点「记进展」。")}</p>{t.activity&&<p className="hint">{ui("已关联")}{t.activity.kind==='reading'?ui("阅读"):t.activity.kind==='german'?ui("学习"):ui("训练")}{ui("：在事项旁点「记录进度」即可补数量、页码或成果。")}</p>}{(!t.activity||t.activity.kind==='german')&&(d.existing?<LearningLinkEditor state={state} selection={{kind:'task',id:d.id}} mutate={mutate} busy={busy} onDone={close}/>:<LearningChoice state={state} value={t.activity?.refId||''} onChange={id=>{const c=state.life.courses.find(c=>c.id===id);set('activity',c?{kind:'german',refId:c.id,category:c.category}:null);}}/>)}<label>{ui('记录类型')}<select value={t.recordType||'activity'} onChange={e=>set('recordType',e.target.value)}><option value="activity">{ui('学习 / 阅读')}</option><option value="project">{ui('项目版本与成果')}</option><option value="practice">{ui('普通练习')}</option></select></label><label>{ui('任务类型')}<select value={entryKind} onChange={e=>setEntryKind(e.target.value as typeof entryKind)}><option value="once">{ui('一次性任务')}</option><option value="long-term">{ui('长期常驻')}</option><option value="stage">{ui('阶段性常驻')}</option></select></label>{entryKind!=='once'&&<p className="hint">{ui('只保存入口，不自动排期；已有任务、实际投入与课程数量保持不变。')}</p>}<label>{ui("事项标题 *")}<input autoFocus required maxLength={200} value={t.title} onChange={e=>set('title',e.target.value)} placeholder={ui("想要推进什么？")}/></label>{live?.plans?<TaskScheduleSummary task={live} state={state} busy={busy} onAdjust={()=>setScheduleOpen(true)}/>:<><div className="fields cols-3"><label>{ui("安排日期")}<input type="date" value={t.date} onInput={e=>set('date',e.currentTarget.value)} onChange={e=>set('date',e.target.value)}/></label><label>{ui("计划开始")}<input type="time" value={t.start} onInput={e=>set('start',e.currentTarget.value)} onChange={e=>set('start',e.target.value)}/></label><label>{ui("计划结束")}<input aria-label={ui("结束时间")} type="time" value={end==='24:00'?'00:00':end} onInput={e=>{if(t.start&&minuteOf(e.currentTarget.value)>minuteOf(t.start))set('minutes',minuteOf(e.currentTarget.value)-minuteOf(t.start));}} onChange={e=>{if(t.start&&minuteOf(e.target.value)>minuteOf(t.start))set('minutes',minuteOf(e.target.value)-minuteOf(t.start));}}/></label></div><div className="chips"><button type="button" onClick={()=>set('date',businessDate(state.settings))}>{ui("今天")}</button><button type="button" onClick={()=>set('date',offsetDate(businessDate(state.settings),1))}>{ui("明天")}</button><button type="button" onClick={()=>{set('date','');set('start','');}}>{ui("先不定日期")}</button></div></>}{!live?.plans&&<><div className="fields cols-2"><DurationInput label={ui("预计用时")} value={t.minutes} max={1440} onChange={v=>set('minutes',v??0)}/><p className="hint">{ui("预计用时是整项任务的总投入，可拆成多次完成。已投入")}{fmt(t.actual||0)}{ui("；用「记进展」补记本次时长或百分比。")}</p></div><div className="chips">{[30,60,90,120,180].map(n=><button key={n} type="button" onClick={()=>set('minutes',n)}>{fmt(n)}</button>)}<button type="button" onClick={()=>set('minutes',0)}>{ui("不填时长")}</button></div></>}<details className="task-editor-extra"><summary>{ui("更多设置 · 项目、重复、分类与关联时段")}</summary><div className="fields cols-2"><label>{ui("包含于 / 并行于时段")}<select value={t.parentId} onChange={e=>set('parentId',e.target.value)}><option value="">{ui("独立安排")}</option>{liveTasks(state).filter(p=>p.id!==d.id&&p.date===t.date&&p.start&&!p.parentId).map(p=><option key={p.id} value={p.id}>{p.start} · {p.title}</option>)}</select></label><label>{ui("关系")}<select value={t.relation} disabled={!t.parentId} onChange={e=>set('relation',e.target.value)}><option value="contained">{ui("包含于：在这个时段内完成")}</option><option value="parallel">{ui("并行于：同时进行")}</option></select></label></div><p className="hint">{ui("包含关系只用于当天这一项。可不填写子任务的开始时间；它的预计投入单独保留，但不额外占用日历。移动父时段会一起移动子任务。")}</p><div className="fields cols-3"><label>{ui("所属项目")}<select value={t.projectId} onChange={e=>set('projectId',e.target.value)}><option value="">{ui("独立事项")}</option>{liveProjects(state).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>{ui("模块")}<select value={t.moduleId} onChange={e=>set('moduleId',e.target.value)}><option value="">{ui("未分模块")}</option>{state.modules.filter(m=>m.projectId===t.projectId).map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></label><label>{ui("分类（可自定义）")}<input value={t.category} required maxLength={40} list="task-categories" onChange={e=>set('category',e.target.value)}/><datalist id="task-categories">{[...new Set(['默认','生活','工作','学习','社交','重要','运动','家务','其他',...state.tasks.map(t=>t.category)])].map(v=><option key={v} value={v}/>)}</datalist></label></div><div className="fields cols-3"><label>{ui("重复")}<select disabled={!!d.existing?.seriesId&&d.scope==='one'} value={d.repeat?.frequency||''} onChange={e=>{setDirty(true);setD(p=>({...p,repeat:e.target.value?{frequency:e.target.value as Repeat['frequency'],days:p.repeat?.days||[],until:p.repeat?.until||''}:null}));}}><option value="">{ui("不重复")}</option>{[['daily','每天'],['weekdays','工作日'],['weekly','每周'],['biweekly','每两周'],['monthly','每月'],['custom','自定义星期']].map(([v,n])=><option key={v} value={v}>{ui(n)}</option>)}</select></label>{d.repeat&&<label>{ui("重复截止（可空）")}<input type="date" value={d.repeat.until} onChange={e=>setD(p=>({...p,repeat:{...p.repeat!,until:e.target.value}}))}/></label>}<label>{ui("事项截止日期")}<input type="date" value={t.deadline} onChange={e=>set('deadline',e.target.value)}/></label></div>{d.repeat?.frequency==='custom'&&<div className="weekday-choices">{['一','二','三','四','五','六','日'].map((v,i)=><label key={v}><input type="checkbox" checked={d.repeat!.days.includes(i)} onChange={e=>setD(p=>({...p,repeat:{...p.repeat!,days:e.target.checked?[...p.repeat!.days,i]:p.repeat!.days.filter(x=>x!==i)}}))}/>{ui("周"+v)}</label>)}</div>}{d.repeat&&<p className="hint">{ui("自动保持未来 90 天的日程；继续使用时向后补齐。没有截止日期也不会提前生成无限记录。")}</p>}{d.existing?.seriesId&&<label>{ui("修改范围")}<select value={d.scope} onChange={e=>setD(p=>({...p,scope:e.target.value as TaskDraft['scope']}))}><option value="one">{ui("仅此次")}</option><option value="future">{ui("此次及以后未完成的事项")}</option><option value="series">{ui("整组未完成的事项")}</option></select><small>{ui("已完成的历史记录不批量改写。整组调整时保持当前安排日期；修改重复频率请先选整组或此次及以后。")}</small></label>}</details><label>{ui("备注")}<textarea rows={3} maxLength={4000} value={t.note} onChange={e=>set('note',e.target.value)}/></label><div className="form-footer">{d.existing&&<button className="danger" type="button" onClick={()=>remove(d.scope)}><Trash2 size={15}/>{ui("删除")}{d.scope==='one'?ui("此事项"):ui("所选范围")}</button>}<button type="button" onClick={()=>template({...t,date:'',start:'',actual:null,progress:0})}><Copy size={15}/>{ui("存为常驻模板")}</button><span className="spacer"/><button type="button" onClick={dismiss}>{ui("取消")}</button><button className="primary" type="submit">{busy?ui("保存中…"):ui("保存事项")}</button></div></fieldset></form>}</Dialog>;
}
function ProjectEditor({project,modules,busy,save,close,remove,guideHint}:{project:Project|null;modules:Module[];busy:boolean;save:(id:string,p:ProjectInput,m:{id:string;name:string}[])=>Promise<void>;close:()=>void;remove:()=>void;guideHint?:string}){
 const [id]=useState(project?.id||uid()),[p,setP]=useState<ProjectInput>(project?projectInput.parse(project):{...projectInput.parse({name:'新项目'}),name:''}),[mods,setMods]=useState(modules.filter(m=>m.projectId===project?.id).map(m=>({id:m.id,name:m.name}))),[dirty,setDirty]=useState(false);
 const change=(key:keyof ProjectInput,value:unknown)=>{setP(v=>({...v,[key]:value}));setDirty(true);};const dismiss=()=>{if(!dirty||confirm(ui("放弃尚未保存的项目修改？")))close();};
 return <Dialog title={project?ui("编辑项目"):ui("新建项目")} onClose={dismiss} wide><form onSubmit={e=>{e.preventDefault();void save(id,p,mods);}}><fieldset disabled={busy}><p className="muted">{guideHint||ui("先拆成可以完成的小步，再找到每天的节奏。")}</p><label>{ui("项目名称 *")}<input required autoFocus maxLength={80} value={p.name} onChange={e=>change('name',e.target.value)}/></label><label>{ui("项目备注")}<textarea rows={3} maxLength={4000} value={p.note} onChange={e=>change('note',e.target.value)}/></label><div className="fields cols-3"><label>{ui("开始日期")}<input type="date" value={p.start} onChange={e=>change('start',e.target.value)}/></label><label>{ui("截止日期")}<input type="date" value={p.deadline} onChange={e=>change('deadline',e.target.value)}/></label><label>{ui("项目颜色")}<input type="color" value={p.color} onChange={e=>change('color',e.target.value)}/></label></div><p className="hint">{ui("不设截止日期，作为长期项目持续推进。")}</p><label>{ui("项目进度计算方式")}<select value={p.progressBasis??'tasks'} onChange={e=>change('progressBasis',e.target.value)}><option value="tasks">{ui("按任务完成度")}</option><option value="time">{ui("按投入时长")}</option></select></label><label>{ui("项目状态")}<select value={p.status} onChange={e=>change('status',e.target.value)}><option value="active">{ui("推进中")}</option><option value="completed">{ui("项目已完成")}</option><option value="archived">{ui("已归档")}</option></select></label><h3 className="subheading">{ui("模块")}</h3>{mods.map((m,i)=><div key={m.id} className="module-edit"><input aria-label={tr("模块 {0}",i+1)} required maxLength={100} value={m.name} onChange={e=>{setDirty(true);setMods(v=>v.map(x=>x.id===m.id?{...x,name:e.target.value}:x));}}/><button type="button" aria-label={tr("移除模块 {0}",m.name)} onClick={()=>{setDirty(true);setMods(v=>v.filter(x=>x.id!==m.id));}}><X size={16}/></button></div>)}<button type="button" onClick={()=>{setDirty(true);setMods(v=>[...v,{id:uid(),name:''}]);}}><Plus size={15}/>{ui("新增模块")}</button><p className="hint">{ui("移除模块会把其中任务移到“未分模块”，不会删除任务。")}</p><h3 className="subheading">{ui("阶段成果")}</h3>{p.goals.map((g,i)=><div className="goal-editor" key={g.id}><input aria-label={tr("成果 {0}",i+1)} placeholder={ui("例如 完成课程章节")} required value={g.title} onChange={e=>change('goals',p.goals.map(x=>x.id===g.id?{...x,title:e.target.value}:x))}/><input aria-label={ui("已完成数量")} type="number" min={0} value={g.current} onChange={e=>change('goals',p.goals.map(x=>x.id===g.id?{...x,current:Number(e.target.value)}:x))}/><span>/</span><input aria-label={ui("目标数量")} type="number" min={1} value={g.target} onChange={e=>change('goals',p.goals.map(x=>x.id===g.id?{...x,target:Number(e.target.value)}:x))}/><input aria-label={ui("成果单位")} placeholder={ui("个")} value={g.unit} onChange={e=>change('goals',p.goals.map(x=>x.id===g.id?{...x,unit:e.target.value}:x))}/><button aria-label={ui("移除此成果")} type="button" onClick={()=>change('goals',p.goals.filter(x=>x.id!==g.id))}><X size={15}/></button></div>)}<button type="button" onClick={()=>change('goals',[...p.goals,{id:uid(),title:'',current:0,target:10,unit:'项'}])}><Plus size={15}/>{ui("新增成果目标")}</button><div className="form-footer">{project&&<button type="button" className="danger" onClick={remove}><Trash2 size={15}/>{ui("删除项目")}</button>}<span className="spacer"/><button type="button" onClick={dismiss}>{ui("取消")}</button><button className="primary" type="submit">{ui("保存项目")}</button></div></fieldset></form></Dialog>;
}
