function ImportDialog({state,today,busy,mutate,close}:{state:State;today:string;busy:boolean;mutate:Mutation;close:()=>void}){
 const [file,setFile]=useState<File|null>(null),[from,setFrom]=useState(today),[to,setTo]=useState(offsetDate(today,180)),[preview,setPreview]=useState<{kind:string;payload:unknown;count:number;names:string[]}|null>(null),[error,setError]=useState(''),[reading,setReading]=useState(false);
 const read=async()=>{if(!file)return;setReading(true);setError('');setPreview(null);try{if(file.size>8_000_000)throw new Error('文件不能超过 8 MB。');const text=await file.text();if(file.name.toLowerCase().endsWith('.json')){const {validateState}=await import('../lib/model');const parsed=JSON.parse(text);const value=validateState(parsed.sync&&parsed.backup?parsed.backup:parsed);setPreview({kind:'backup',payload:value,count:value.tasks.length,names:value.projects.map(p=>p.name)});}else{if(from>to)throw new Error('结束日期不能早于开始日期。');const records=file.name.toLowerCase().endsWith('.ics')?await icsImport(text,state,from,to):await csvImport(text,state);const fresh=records.filter(t=>!state.tasks.some(x=>x.id===t.id));setPreview({kind:'tasks',payload:fresh,count:fresh.length,names:fresh.slice(0,12).map(t=>`${t.date||'未排期'} ${t.start} · ${t.title}`)});}}catch(e){setError(e instanceof Error?e.message:ui("无法读取文件"));}finally{setReading(false);}};
 return <Dialog title={ui("导入与恢复")} onClose={close} wide><p className="muted">{ui("先预览，再写入。支持本工作台备份、CSV 事项表和 ICS 日历。")}</p><label>{ui("选择文件")}<input type="file" accept=".json,.csv,.ics" onChange={e=>{setFile(e.target.files?.[0]||null);setPreview(null);setError('');}}/></label>{file?.name.toLowerCase().endsWith('.ics')&&<><div className="fields cols-2"><label>{ui("从")}<input type="date" value={from} onChange={e=>{setFrom(e.target.value);setPreview(null);}}/></label><label>{ui("至")}<input type="date" value={to} onChange={e=>{setTo(e.target.value);setPreview(null);}}/></label></div><p className="hint">{ui("按指定日期展开课表；支持常见每日、每周、隔周、每月规则。再次导入同一事件会跳过已有记录。")}</p></>}{error&&<p role="alert" className="inline-error">{ui(error)}</p>}<button disabled={!file||reading||busy} onClick={()=>void read()}>{reading?ui("读取中…"):ui("预览文件")}</button>{preview&&<div className="import-preview"><h3>{preview.kind==='backup'?ui("完整恢复"):ui("新增事项")} · {preview.count} {ui("条任务记录")}</h3>{preview.names.map((n,i)=><p key={i}>{n}</p>)}{preview.kind==='backup'&&<p className="warning">{ui("确认后会替换现有全部数据。请先在“数据与导出”下载当前备份。")}</p>}<button className="primary" disabled={busy||preview.kind==='tasks'&&!preview.count} onClick={async()=>{if(preview.kind==='backup'&&!confirm(ui("确定用此备份替换当前全部工作台数据？")))return;if(await mutate({type:preview.kind==='backup'?'backup.import':'tasks.import',payload:preview.payload},ui("导入完成，数据已保存。")))close();}}>{ui("确认")}{preview.kind==='backup'?ui("恢复并替换"):ui("导入")}</button></div>}</Dialog>;
}
